/**
 * emit to subscription queries of type FindQuarantine,
 * but only if the id matches
 *
 * @param		entity	Quarantine
 */
	protected void emitFindQuarantine( Quarantine entity ) {
		LOGGER.info("handling emitFindQuarantine" );
		
	    queryUpdateEmitter.emit(FindQuarantineQuery.class,
	                            query -> query.getFilter().getQuarantineId().equals(entity.getQuarantineId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllQuarantine
	 * 
	 * @param		entity	Quarantine
	 */
	protected void emitFindAllQuarantine( Quarantine entity ) {
		LOGGER.info("handling emitFindAllQuarantine" );
		
	    queryUpdateEmitter.emit(FindAllQuarantineQuery.class,
	                            query -> true,
	                            entity);
	}

